import { createMiddleware } from '@tanstack/react-start'
import { isSupabaseClientConfigured, supabase } from './client'

// Must be registered as a global `functionMiddleware` in `src/start.ts`; otherwise
// the browser never attaches the bearer token to serverFn RPCs.
//
// The storefront must still render when Supabase is not configured in a preview
// deployment. Authenticated/admin server functions remain protected server-side;
// this middleware only attaches the browser session when one is available.
export const attachSupabaseAuth = createMiddleware({ type: 'function' }).client(
  async ({ next }) => {
    if (!isSupabaseClientConfigured()) {
      return next({ headers: {} })
    }

    try {
      const { data } = await supabase.auth.getSession()
      const token = data.session?.access_token
      return next({
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
    } catch (error) {
      console.warn('[Supabase] Unable to attach auth session; continuing without auth header.', error)
      return next({ headers: {} })
    }
  },
)
